START TRANSACTION;
SOURCE data/seed/01_reference_data.sql;
SET @p2_b=(SELECT COUNT(*) FROM Branches);
SET @p2_t=(SELECT COUNT(*) FROM Account_Types);
SET @p2_e=(SELECT COUNT(*) FROM Employees);
SOURCE data/seed/01_reference_data.sql;
SET @p2_ok=(SELECT COUNT(*)=@p2_b FROM Branches);
CALL bank_lab.sp_assert_true(DATABASE(),'reference branches repeatable',@p2_ok,'Second load leaves branch row count unchanged');
SET @p2_ok=(SELECT COUNT(*)=@p2_t FROM Account_Types);
CALL bank_lab.sp_assert_true(DATABASE(),'reference types repeatable',@p2_ok,'Second load leaves type row count unchanged');
SET @p2_ok=(SELECT COUNT(*)=@p2_e FROM Employees);
CALL bank_lab.sp_assert_true(DATABASE(),'reference employees repeatable',@p2_ok,'Second load leaves employee row count unchanged');
SET @p2_ok=(SELECT COUNT(*)=3 FROM Branches WHERE ifsc_code IN ('SYNB0000001','SYNB0000002','SYNB0000003'));
CALL bank_lab.sp_assert_true(DATABASE(),'reference three synthetic branches',@p2_ok,'Natural IFSC keys');
SET @p2_ok=(SELECT COUNT(*)=3 FROM Account_Types WHERE (type_name='Savings' AND interest_rate=3.50 AND min_balance=1000) OR (type_name='Current' AND interest_rate=0 AND min_balance=5000) OR (type_name='Fixed Deposit' AND interest_rate=6.50 AND min_balance=10000));
CALL bank_lab.sp_assert_true(DATABASE(),'reference account type rates and minima',@p2_ok,'Exact SPEC reference values');
SET @p2_ok=(SELECT COUNT(*)=5 FROM Employees e JOIN Branches b USING(branch_id) WHERE e.is_active AND ((e.email='teller.one@example.invalid' AND e.role='Teller' AND b.ifsc_code='SYNB0000001') OR (e.email='teller.two@example.invalid' AND e.role='Teller' AND b.ifsc_code='SYNB0000002') OR (e.email='manager.one@example.invalid' AND e.role='Manager' AND b.ifsc_code='SYNB0000001') OR (e.email='manager.two@example.invalid' AND e.role='Manager' AND b.ifsc_code='SYNB0000002') OR (e.email='dba@example.invalid' AND e.role='DBA' AND b.ifsc_code='SYNB0000001')));
CALL bank_lab.sp_assert_true(DATABASE(),'reference five employee assignments',@p2_ok,'Branch resolved by natural key, never assumed surrogate id');
ROLLBACK;
